using System;using System.Text;using System.Collections.Generic;using System.IO;using System.Linq;using System.Net;using System.Globalization;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Runtime.InteropServices;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Media;using System.Windows.Interop;using System.Windows.Threading;
namespace GlassBoard {
    [DataContract] public class GeoPlace{[DataMember(Name="name")]public string Name;[DataMember(Name="country")]public string Country;[DataMember(Name="latitude")]public double Latitude;[DataMember(Name="longitude")]public double Longitude;}
    [DataContract] public class GeoReply{[DataMember(Name="results")]public List<GeoPlace> Results;}
    [DataContract] public class WeatherCurrent{[DataMember(Name="temperature_2m")]public double Temperature;[DataMember(Name="weather_code")]public int Code;[DataMember(Name="wind_speed_10m")]public double Wind;[DataMember(Name="time")]public string Time;[DataMember]public string Description;}
    [DataContract] public class WeatherReply{[DataMember(Name="current")]public WeatherCurrent Current;}
    public class WeatherSnapshot{public GeoPlace Place;public WeatherCurrent Current;public string Provider;}
    [DataContract] public class WttrText {[DataMember(Name="value")]public string Value;}
    [DataContract] public class WttrArea {[DataMember(Name="areaName")]public List<WttrText> Name;[DataMember(Name="country")]public List<WttrText> Country;[DataMember(Name="latitude")]public string Latitude;[DataMember(Name="longitude")]public string Longitude;}
    [DataContract] public class WttrCurrent {[DataMember(Name="temp_C")]public string Temperature;[DataMember(Name="windspeedKmph")]public string Wind;[DataMember(Name="weatherDesc")]public List<WttrText> Description;[DataMember(Name="lang_zh")]public List<WttrText> Chinese;[DataMember(Name="lang_xx")]public List<WttrText> Localized;}
    [DataContract] public class WttrReply {[DataMember(Name="current_condition")]public List<WttrCurrent> Current;[DataMember(Name="nearest_area")]public List<WttrArea> Areas;}
    public static class WeatherClient {
        static readonly object gate=new object();static readonly Dictionary<string,GeoPlace> places=new Dictionary<string,GeoPlace>(StringComparer.OrdinalIgnoreCase);
        static readonly Dictionary<string,string> aliases=new Dictionary<string,string>{{"北京","Beijing"},{"上海","Shanghai"},{"天津","Tianjin"},{"重庆","Chongqing"},{"杭州","Hangzhou"},{"广州","Guangzhou"},{"深圳","Shenzhen"},{"南京","Nanjing"},{"成都","Chengdu"},{"武汉","Wuhan"},{"西安","Xi'an"},{"苏州","Suzhou"},{"郑州","Zhengzhou"},{"长沙","Changsha"},{"济南","Jinan"},{"青岛","Qingdao"},{"沈阳","Shenyang"},{"大连","Dalian"},{"哈尔滨","Harbin"},{"长春","Changchun"},{"福州","Fuzhou"},{"厦门","Xiamen"},{"昆明","Kunming"},{"贵阳","Guiyang"},{"南宁","Nanning"},{"南昌","Nanchang"},{"合肥","Hefei"},{"石家庄","Shijiazhuang"},{"太原","Taiyuan"},{"兰州","Lanzhou"},{"西宁","Xining"},{"银川","Yinchuan"},{"乌鲁木齐","Urumqi"},{"拉萨","Lhasa"},{"海口","Haikou"},{"香港","Hong Kong"},{"澳门","Macau"},{"台北","Taipei"}};
        public static string NormalizeCity(string city){city=(city??"").Trim().Normalize(NormalizationForm.FormKC).Replace('，',',');if(city.IndexOf(',')>=0)return city;int province=city.LastIndexOf('省');if(province>=0&&province<city.Length-1)city=city.Substring(province+1);if(city.Length>2&&city.EndsWith("市",StringComparison.Ordinal))city=city.Substring(0,city.Length-1);return city.Trim();}
        public static T Read<T>(Stream stream){return WeatherTransport.Read<T>(stream);}
        static T Get<T>(string url){return WeatherTransport.Get<T>(url,false);}
        public static bool Coordinates(string value,out GeoPlace place){place=null;var parts=(value??"").Split(',');double lat,lon;if(parts.Length!=2||!double.TryParse(parts[0],NumberStyles.Float,CultureInfo.InvariantCulture,out lat)||!double.TryParse(parts[1],NumberStyles.Float,CultureInfo.InvariantCulture,out lon)||double.IsNaN(lat)||double.IsNaN(lon)||double.IsInfinity(lat)||double.IsInfinity(lon)||Math.Abs(lat)>90||Math.Abs(lon)>180)return false;place=new GeoPlace{Name=value,Country="经纬度",Latitude=lat,Longitude=lon};return true;}
        static GeoPlace Resolve(string city,Func<string,GeoReply> reader){GeoPlace cached;if(Coordinates(city,out cached))return cached;lock(gate)if(places.TryGetValue(city,out cached))return cached;
            string alias;var queries=new List<string>{city};if(aliases.TryGetValue(city,out alias))queries.Add(alias+", "+(city=="台北"?"TW":city=="香港"?"HK":city=="澳门"?"MO":"CN"));
            foreach(var query in queries){var geo=reader("https://geocoding-api.open-meteo.com/v1/search?count=10&language=zh&format=json&name="+Uri.EscapeDataString(query));if(geo!=null&&geo.Results!=null&&geo.Results.Count>0){var place=geo.Results.FirstOrDefault(x=>NormalizeCity(x.Name).Equals(city,StringComparison.OrdinalIgnoreCase))??geo.Results[0];lock(gate){if(places.Count>=100)places.Clear();places[city]=place;}return place;}}
            throw new InvalidOperationException("未找到城市，请填写城市名、城市加国家，或纬度,经度");
        }
        static string Text(List<WttrText> values){return values==null?"":string.Join(" ",values.Where(x=>x!=null&&!string.IsNullOrWhiteSpace(x.Value)).Select(x=>x.Value));}
        public static WeatherSnapshot FromWttr(WttrReply reply){if(reply==null||reply.Current==null||reply.Current.Count==0||reply.Areas==null||reply.Areas.Count==0)throw new InvalidDataException("备用天气服务未返回有效地点和天气");var current=reply.Current[0];var area=reply.Areas[0];double temperature,wind;GeoPlace place;if(!double.TryParse(current.Temperature,NumberStyles.Float,CultureInfo.InvariantCulture,out temperature)||!double.TryParse(current.Wind,NumberStyles.Float,CultureInfo.InvariantCulture,out wind)||double.IsNaN(temperature)||double.IsInfinity(temperature)||temperature < -100||temperature>70||double.IsNaN(wind)||double.IsInfinity(wind)||wind<0||!Coordinates(area.Latitude+","+area.Longitude,out place))throw new InvalidDataException("备用天气数据格式不正确");place.Name=Text(area.Name);place.Country=Text(area.Country);if(string.IsNullOrWhiteSpace(place.Name)||string.IsNullOrWhiteSpace(place.Country))throw new InvalidDataException("备用天气服务未返回地点名称");string description=Text(current.Chinese);if(!System.Text.RegularExpressions.Regex.IsMatch(description??"",@"[\u3400-\u9fff]")&&System.Text.RegularExpressions.Regex.IsMatch(Text(current.Localized),@"[\u3400-\u9fff]"))description=Text(current.Localized);if(string.IsNullOrWhiteSpace(description))description=Text(current.Description);description=WeatherPresentation.Description(-1,description);return new WeatherSnapshot{Place=place,Provider="wttr.in",Current=new WeatherCurrent{Temperature=temperature,Wind=wind,Description=description,Code=-1}};}
        public static string Failure(Exception exception){var ex=exception.GetBaseException();var network=exception as WebException??ex as WebException;if(network!=null){if(network.Status==WebExceptionStatus.Timeout)return "天气服务连接超时";if(network.Status==WebExceptionStatus.NameResolutionFailure||network.Status==WebExceptionStatus.ProxyNameResolutionFailure)return "天气域名或代理解析失败";if(network.Status==WebExceptionStatus.TrustFailure||network.Status==WebExceptionStatus.SecureChannelFailure)return "天气 HTTPS 连接失败，请检查系统时间和证书";var response=network.Response as HttpWebResponse;if(response!=null)return "天气服务返回 HTTP "+(int)response.StatusCode;return "天气服务连接失败，请检查网络或系统代理";}return ex is InvalidOperationException||ex is ArgumentException?ex.Message:"天气数据暂不可用";}
        public static WeatherSnapshot Fetch(string city){return Fetch(city,false);}
        public static WeatherSnapshot Fetch(string city,bool direct){return Fetch(city,url=>WeatherTransport.Get<GeoReply>(url,direct),url=>WeatherTransport.Get<WeatherReply>(url,direct),url=>WeatherTransport.Get<WttrReply>(url,direct));}
        // Injected readers keep failure routing testable without depending on live weather.
        public static WeatherSnapshot Fetch(string city,Func<string,GeoReply> geoReader,Func<string,WeatherReply> forecastReader,Func<string,WttrReply> backupReader){
            if(string.IsNullOrWhiteSpace(city))throw new ArgumentException("请先在设置中填写天气城市");city=NormalizeCity(city);GeoPlace place=null;Exception failure=null;
            try{place=Resolve(city,geoReader);string lat=place.Latitude.ToString(CultureInfo.InvariantCulture),lon=place.Longitude.ToString(CultureInfo.InvariantCulture);var forecast=forecastReader("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,weather_code,wind_speed_10m&timezone=auto");if(forecast==null||forecast.Current==null)throw new InvalidDataException("天气服务没有返回当前数据");return new WeatherSnapshot{Place=place,Current=forecast.Current,Provider="Open-Meteo"};}catch(Exception ex){failure=ex;}
            try{string query=place==null?city:place.Latitude.ToString(CultureInfo.InvariantCulture)+","+place.Longitude.ToString(CultureInfo.InvariantCulture);return FromWttr(backupReader("https://wttr.in/"+Uri.EscapeDataString(query)+"?format=j1&lang=zh"));}catch(Exception backup){throw new InvalidOperationException("主服务："+Failure(failure)+"；备用服务："+Failure(backup),new AggregateException("天气主备请求均失败",failure,backup));}
        }
    }
    public static class SystemMedia {
        [StructLayout(LayoutKind.Sequential)] struct MOUSEINPUT{public int X,Y;public uint Data,Flags,Time;public IntPtr Extra;}
        [StructLayout(LayoutKind.Sequential)] struct KEYBDINPUT{public ushort Key,Scan;public uint Flags,Time;public IntPtr Extra;}
        [StructLayout(LayoutKind.Explicit)] struct UNION{[FieldOffset(0)]public MOUSEINPUT Mouse;[FieldOffset(0)]public KEYBDINPUT Keyboard;}
        [StructLayout(LayoutKind.Sequential)] struct INPUT{public uint Type;public UNION Value;}
        [DllImport("user32.dll",SetLastError=true)] static extern uint SendInput(uint count,INPUT[] input,int size);
        public static void Shortcut(ushort modifier,ushort key){var inputs=new[]{new INPUT{Type=1,Value=new UNION{Keyboard=new KEYBDINPUT{Key=modifier}}},new INPUT{Type=1,Value=new UNION{Keyboard=new KEYBDINPUT{Key=key}}},new INPUT{Type=1,Value=new UNION{Keyboard=new KEYBDINPUT{Key=key,Flags=2}}},new INPUT{Type=1,Value=new UNION{Keyboard=new KEYBDINPUT{Key=modifier,Flags=2}}}};if(SendInput(4,inputs,Marshal.SizeOf(typeof(INPUT)))!=4)throw new InvalidOperationException("无法打开系统快捷面板");}
        public static void Key(ushort key){var down=new INPUT{Type=1,Value=new UNION{Keyboard=new KEYBDINPUT{Key=key}}};var up=new INPUT{Type=1,Value=new UNION{Keyboard=new KEYBDINPUT{Key=key,Flags=2}}};if(SendInput(2,new INPUT[]{down,up},Marshal.SizeOf(typeof(INPUT)))!=2)throw new InvalidOperationException("无法发送系统媒体键");}
    }
}
